interface Args { src: string; out: string; nep: string; datasets: DatasetKey[]; pdf: boolean }
function parseArgs(): Args {
  const argv = process.argv.slice(2);
  const get = (k: string) => argv.find((a) => a.startsWith(`--${k}=`))?.slice(k.length + 3);
  const ds = (get("dataset") ?? DATASET_ORDER.join(",")).split(",").map((s) => s.trim()).filter(Boolean);
  for (const d of ds) if (!DATASET_ORDER.includes(d as DatasetKey)) throw new Error(`unknown dataset ${d}`);
  return {
    src: resolve(get("src") ?? "/tmp/dpwh-nep-review/repo"),
    out: resolve(get("out") ?? "data/hgab/2027"),
    nep: resolve(get("nep") ?? "data/2027"),
    datasets: DATASET_ORDER.filter((d) => ds.includes(d)),
    pdf: !argv.includes("--no-pdf"),
  };
}

const q = (s: string) => s.replace(/'/g, "''");
const peso = (n: number | null | undefined) => (n == null ? "—" : `₱${n.toLocaleString("en-US")}`);
const sum = <T,>(rows: T[], f: (r: T) => number | null | undefined) => rows.reduce((a, r) => a + (f(r) ?? 0), 0);
const log = (s: string) => process.stdout.write(`${s}\n`);

function ensure(cond: unknown, msg: string): asserts cond {
  if (!cond) throw new Error(msg);
}
function readJson<T>(path: string): T {
  return JSON.parse(readFileSync(path, "utf8")) as T;
}
function sha256(path: string): string {
  return createHash("sha256").update(readFileSync(path)).digest("hex");
}
function intOrNull(v: unknown): number | null {
  return typeof v === "number" && Number.isFinite(v) ? v : null;
}
function strOrNull(v: unknown): string | null {
  return typeof v === "string" && v !== "" ? v : null;
}
function searchText(parts: Array<string | null | undefined>): string {
  return parts.map((p) => (p ?? "").toString().toLowerCase().replace(/\s+/g, " ").trim()).join("|");
}
function stripRecord(r: OutRow): ProjectRow {
  const { record_json: _record, ...rest } = r;
  void _record;
  return rest;
}
function topBy(items: Built[], group: BridgeGroup, n = 25): ProjectRow[] {
  const basis = (b: Built): number => {
    switch (group) {
      case "house_only": return b.house ?? 0;
      case "nep_only": return b.nep ?? 0;
      case "unchanged": return b.house ?? 0;
      case "increased": return b.delta;
      case "decreased": return -b.delta;
      case "scope_review": return Math.abs(b.delta);
    }
  };
  return items.filter((b) => b.group === group)
    .sort((a, b) => basis(b) - basis(a) || a.row.id.localeCompare(b.row.id))
    .slice(0, n).map((b) => stripRecord(b.row));
}

/** One output row plus what the bridge needs: its group and the booked delta. */
interface Built { row: OutRow; group: BridgeGroup; house: number | null; nep: number | null; delta: number }

function groupOf(house: number | null, nep: number | null, segmentScope: boolean): BridgeGroup {
  if (house != null && nep == null) return "house_only";
  if (nep != null && house == null) return "nep_only";
  ensure(house != null && nep != null, "row has neither side");
  if (segmentScope) return "scope_review";
  if (house > nep) return "increased";
  if (house < nep) return "decreased";
  return "unchanged";
}

/** overviewSummary.js partition() semantics over our built rows. */
function bridgeOf(items: Built[], houseStage: "hgab2" | "hgab3"): Bridge {
  const cell = (g: BridgeGroup): BridgeCell => {
    const rows = items.filter((b) => b.group === g);
    const house = sum(rows, (b) => b.house), nep = sum(rows, (b) => b.nep);
    switch (g) {
      case "house_only": return { rows: rows.length, php: house, nep_php: null, house_php: house };
      case "nep_only": return { rows: rows.length, php: nep, nep_php: nep, house_php: null };
      case "unchanged": ensure(house === nep, "unchanged pairs carry different totals"); return { rows: rows.length, php: house, nep_php: nep, house_php: house };
      case "increased": return { rows: rows.length, php: sum(rows, (b) => b.delta), nep_php: nep, house_php: house };
      case "decreased": return { rows: rows.length, php: -sum(rows, (b) => b.delta), nep_php: nep, house_php: house };
      case "scope_review": return { rows: rows.length, php: sum(rows, (b) => b.delta), nep_php: nep, house_php: house };
    }
  };
  const bridge: Bridge = {
    house_only: cell("house_only"), nep_only: cell("nep_only"), unchanged: cell("unchanged"),
    increased: cell("increased"), decreased: cell("decreased"), scope_review: cell("scope_review"),
    net_php: sum(items, (b) => b.house) - sum(items, (b) => b.nep), house_stage: houseStage,
  };
  const identity = bridge.house_only.php - bridge.nep_only.php + bridge.increased.php - bridge.decreased.php + bridge.scope_review.php;
  ensure(identity === bridge.net_php, `bridge identity failed: ${identity} vs ${bridge.net_php}`);
  return bridge;
}

/** main_overview_2027.json workspace block (overviewSummary.js output). */
interface MainWorkspace {
  key: string; delta_php: number;
  sources: { house: { count: number; amount_php: number }; nep: { count: number; amount_php: number } };
  insertions: { count: number; comparison_rows?: number; amount_php: number };
  deletions: { count: number; comparison_rows?: number; amount_php: number };
  unchanged: { count: number; comparison_rows?: number; amount_php: number };
  adjustments: { increased_count: number; reduced_count: number; increased_php: number; reduced_php: number; net_php: number };
  scope_review?: { count: number; net_php: number };
  readings?: { second: { count: number; amount_php: number } | null; third: { count: number; amount_php: number } };
}
function assertBridgeMatches(key: DatasetKey, bridge: Bridge, ws: MainWorkspace): void {
  const checks: Array<[string, number, number]> = [
    ["house_only php", bridge.house_only.php, ws.insertions.amount_php],
    ["house_only rows", bridge.house_only.rows, ws.insertions.comparison_rows ?? ws.insertions.count],
    ["nep_only php", bridge.nep_only.php, ws.deletions.amount_php],
    ["nep_only rows", bridge.nep_only.rows, ws.deletions.comparison_rows ?? ws.deletions.count],
    ["unchanged php", bridge.unchanged.php, ws.unchanged.amount_php],
    ["unchanged rows", bridge.unchanged.rows, ws.unchanged.comparison_rows ?? ws.unchanged.count],
    ["increased php", bridge.increased.php, ws.adjustments.increased_php],
    ["increased rows", bridge.increased.rows, ws.adjustments.increased_count],
    ["decreased php", bridge.decreased.php, ws.adjustments.reduced_php],
    ["decreased rows", bridge.decreased.rows, ws.adjustments.reduced_count],
    ["scope_review php", bridge.scope_review.php, ws.scope_review?.net_php ?? 0],
    ["scope_review rows", bridge.scope_review.rows, ws.scope_review?.count ?? 0],
    ["net php", bridge.net_php, ws.delta_php],
  ];
  const bad = checks.filter(([, a, b]) => a !== b);
  ensure(bad.length === 0, `${key} bridge differs from main_overview_2027.json: ${bad.map(([n, a, b]) => `${n} ${a} vs ${b}`).join("; ")}`);
}

