/** analysis/viewers/project_offices.mjs canonicalOffice(), ported verbatim. */
function canonicalOffice(office: unknown): string {
  if (office == null || office === "") return "";
  let s = String(office).normalize("NFKC").trim().replace(/\s+/g, " ");
  let prev: string;
  do {
    prev = s;
    s = s.replace(/(\p{L})\s*ñ\s*(\p{L})/gu, (_, a: string, b: string) => `${a}ñ${b}`);
  } while (s !== prev);
  if (/District Engineering Office$/i.test(s)) s = s.replace(/\s*-\s*/g, " ").replace(/\s+/g, " ");
  s = s.replace(/^(Regional Office )([IVXLC]+)([AB])$/i, (_, p: string, n: string, l: string) => `${p}${n.toUpperCase()}-${l.toUpperCase()}`);
  s = s.replace(/Marindugue/gi, "Marinduque").replace(/Siguijor/gi, "Siquijor").replace(/Occidenatal/gi, "Occidental")
    .replace(/Batagas/gi, "Batangas").replace(/Ilolilo/gi, "Iloilo");
  return s;
}
function recordedOffice(r: DpwhSide | null | undefined): string {
  if (!r) return "";
  if (r.office_canonical) return r.office_canonical;
  return r.office ? canonicalOffice(r.office) : "";
}
/** analysis/web/src/headlineStats.js officeKind(). */
function officeKind(value: unknown): string {
  const office = String(value ?? "").trim().replace(/\s+/g, " ");
  if (!office) return "No recorded office";
  if (/^central office$/i.test(office)) return "Central Office";
  if (/district engineering office|\bDEO\b/i.test(office)) return "District engineering offices (DEOs)";
  if (/regional office/i.test(office)) return "Regional offices";
  return "Other recorded offices";
}
/** analysis/web/src/comparisonData.js hydrateProjects(). */
function hydrate(rows: DpwhRow[]): DpwhRow[] {
  return rows.map((row) => {
    const result: DpwhRow = { ...row };
    for (const side of ["second", "third", "nep", "api"] as const) {
      const s = row[side];
      if (!s) continue;
      const { inherit = [], ...source } = s;
      result[side] = { ...Object.fromEntries(inherit.map((k) => [k, row[k]])), ...source } as DpwhSide;
    }
    return result;
  });
}
function lengthOf(side: DpwhSide | null | undefined): number | null {
  if (!side?.chainages?.length) return null;
  const spans = side.chainages.filter((c) => !c.point && c.length_review == null && typeof c.length_m === "number" && c.length_m > 0);
  if (!spans.length) return null;
  return spans.reduce((a, c) => a + (c.length_m ?? 0), 0);
}
const NEP_EVIDENCE_REVIEW = new Set(["native_row_ambiguity", "native_text_review", "nearby_alignment_candidate"]);
const EXACT_PAIR = new Set(["exact_candidate"]);

function controlRow(p: DpwhPap): ControlRow {
  const house = p.third_php ?? p.second_php ?? null;
  return {
    id: p.id, label: p.label, group: p.program, nep_php: p.nep_php ?? null, hgab2_php: p.second_php ?? null, hgab3_php: p.third_php ?? null,
    api_php: p.api_php ?? null, delta_php: house != null && p.nep_php != null ? house - p.nep_php : null,
    reading_delta_php: p.reading_delta_php ?? null, nep_page: p.nep_page ?? null,
    house_pages: p.third_pages?.length ? p.third_pages : p.house_pages ?? [],
  };
}

function buildDpwh(src: string, mainWs: MainWorkspace): { meta: HgabDatasetMeta; summary: DatasetSummary; rows: OutRow[]; docPages: Record<string, number[]> } {
  const detail = readJson<{ projects: DpwhRow[] }>(resolve(src, "analysis/data/comparison_projects_2027.json"));
  const overview = readJson<DpwhOverviewPayload>(resolve(src, "analysis/data/comparison_overview_2027.json"));
  const rows = hydrate(detail.projects);
  log(`  dpwh: ${rows.length.toLocaleString()} unified rows`);

  const docPages: Record<string, number[]> = { [DOC.ic2]: [], [DOC.ic3]: [], [DOC.nepIIB]: [], [DOC.ib2]: [], [DOC.ib3]: [] };
  const built: Built[] = rows.map((r) => {
    const house = r.third ?? r.second ?? null;
    const office = recordedOffice(house) || recordedOffice(r.nep) || null;
    const kind = officeKind(office || house?.office || r.nep?.office);
    const segmentScope = r.house_match === "segment_scope_candidate" || String(r.trace).includes("segment_scope_review");
    const nep = intOrNull(r.nep?.amount_php), hgab2 = intOrNull(r.second?.amount_php), hgab3 = intOrNull(r.third?.amount_php);
    const latest = hgab3 ?? hgab2;
    const delta = latest != null && nep != null ? latest - nep : null;

    const flags: string[] = [];
    if (house && !r.nep) flags.push("house_only");
    if (r.nep && !house) flags.push("nep_only");
    if (r.region_difference) flags.push("region_difference");
    if (house && r.nep && recordedOffice(house) && recordedOffice(r.nep) && recordedOffice(house) !== recordedOffice(r.nep)) flags.push("office_difference");
    if (!office) flags.push("no_office");
    if (r.reading_status === "repeated_key") flags.push("repeated_key");
    if (house && r.nep && r.house_match && !EXACT_PAIR.has(r.house_match)) flags.push("uncertain_match");
    if (r.nep?.evidence && NEP_EVIDENCE_REVIEW.has(r.nep.evidence)) flags.push("nep_evidence_review");
    if (house?.chainage_length_review || r.nep?.chainage_length_review) flags.push("length_review");
    if (r.twin_review) flags.push("twin_review");
    if (r.nep_twin) flags.push("nep_twin");
    if (segmentScope) flags.push("segment_scope");
    if (r.api_presence === "nep_not_in_transparency" || String(r.trace).includes("transparency_gap")) flags.push("transparency_gap");
    if (r.api_presence === "outside_api_scope" || String(r.trace).includes("outside_api")) flags.push("outside_api");
    if (r.road_group?.flag === "insertion_candidate_group_exhausted") flags.push("group_exhausted");
    if (r.road_group?.flag === "deletion_candidate_group_house_paired") flags.push("group_nep_leftover");

    const nepPage = intOrNull(r.nep?.pdf_page), p2 = intOrNull(r.second?.pdf_page), p3 = intOrNull(r.third?.pdf_page);
    if (nepPage) docPages[DOC.nepIIB].push(nepPage);
    if (p2) docPages[DOC.ic2].push(p2);
    if (p3) docPages[DOC.ic3].push(p3);

    const row: OutRow = {
      id: r.id, dataset: "dpwh", title: r.title, program: strOrNull(r.program), pap: strOrNull(r.pap), region: strOrNull(r.region),
      office, office_kind: kind, zone: strOrNull(r.zone),
      trace: r.trace, house_match: strOrNull(r.house_match), reading_status: strOrNull(r.reading_status), api_presence: strOrNull(r.api_presence),
      confidence: intOrNull(r.confidence),
      nep_php: nep, hgab2_php: hgab2, hgab3_php: hgab3, api_php: intOrNull(r.api?.amount_php), delta_php: delta,
      nep_page: nepPage, hgab2_page: p2, hgab3_page: p3,
      nep_doc: r.nep ? DOC.nepIIB : null, hgab2_doc: r.second ? DOC.ic2 : null, hgab3_doc: r.third ? DOC.ic3 : null,
      length_m: lengthOf(house) ?? lengthOf(r.nep), flags: flags.join(","), suggestions: r.suggestions?.length ?? 0,
      search_text: searchText([r.title, r.program, r.pap, r.region, office]), record_json: JSON.stringify(r),
    };
    // Bridge is measured against the third reading (overviewSummary.js dpwhSummary).
    const third = intOrNull(r.third?.amount_php);
    return { row, group: groupOf(third, nep, segmentScope), house: third, nep, delta: third != null && nep != null ? third - nep : 0 };
  });

  const bridge = bridgeOf(built, "hgab3");
  assertBridgeMatches("dpwh", bridge, mainWs);

  const S = overview.headlines.sources;
  const totals = { nep_php: S.nep.amount_php, hgab2_php: S.second.amount_php, hgab3_php: S.third.amount_php, api_php: S.api.amount_php };
  const counts = { nep: S.nep.records, hgab2: S.second.records, hgab3: S.third.records, api: S.api.records };
  const memberCount = (side: "second" | "third" | "nep" | "api") => sum(rows, (r) => (r[side] ? r[side]?.records?.length ?? 1 : 0));
  const memberSum = (side: "second" | "third" | "nep" | "api") => sum(rows, (r) => r[side]?.amount_php);
  for (const side of ["second", "third", "nep", "api"] as const) {
    ensure(memberSum(side) === S[side].amount_php && memberCount(side) === S[side].records, `dpwh ${side} rows do not reconcile to headline`);
  }
  ensure(totals.nep_php === EXPECTED.dpwh.nep && totals.hgab2_php === EXPECTED.dpwh.hgab2 && totals.hgab3_php === EXPECTED.dpwh.hgab3 && totals.api_php === EXPECTED.dpwh.api, "dpwh stage totals drifted from expected");
  const printed = {
    nep_new_appropriations_php: overview.summary.stages.official_nep.new_appropriations_php,
    house_new_appropriations_php: overview.readingSummary.third.new_appropriations,
  };
  ensure(printed.nep_new_appropriations_php === EXPECTED.dpwh.printed_nep && printed.house_new_appropriations_php === EXPECTED.dpwh.printed_house
    && overview.readingSummary.second.new_appropriations === EXPECTED.dpwh.printed_house, "dpwh printed new appropriations drifted");

  // PAP controls: source_comparison paps joined to the reading ledger by the workbench (unifiedComparison.js).
  const controls = overview.paps.map(controlRow);
  for (const p of overview.paps) {
    docPages[DOC.ib2].push(...(p.second_pages ?? p.house_pages ?? []));
    docPages[DOC.ib3].push(...(p.third_pages ?? []));
    if (p.nep_page) docPages[DOC.nepIIB].push(p.nep_page);
  }
  // Every PAP with a House control must have been joined to both readings.
  ensure(overview.paps.every((p) => p.house_control_php == null || (p.second_php === p.house_control_php && p.third_php != null)), "PAP control reading join incomplete");

  const dimFrom = (entries: DimEntry[]): DimRow[] => entries.map((e) => ({
    label: e.label, nep_php: e.nep_php, house_php: e.house_php, nep_records: e.nep_records, house_records: e.house_records,
  }));
  const byDim = overview.headlines.sourceCompare.third.by_dim;
  const officeDim: DimRow[] = Object.keys(S.third.offices).map((k) => ({
    label: k, nep_php: S.nep.offices[k]?.amount_php ?? 0, house_php: S.third.offices[k]?.amount_php ?? 0,
    nep_records: S.nep.offices[k]?.records ?? 0, house_records: S.third.offices[k]?.records ?? 0,
  }));
  const dims: Partial<Record<DimKey, DimRow[]>> = {
    region: dimFrom(byDim.region), office_kind: officeDim, program: dimFrom(byDim.program), pap: dimFrom(byDim.pap),
  };
  for (const [k, d] of Object.entries(dims)) {
    ensure(sum(d, (x) => x.house_php) === totals.hgab3_php && sum(d, (x) => x.nep_php) === totals.nep_php, `dpwh dim ${k} does not conserve stage totals`);
  }

  const rs = overview.readingSummary;
  const thirdOnly = built.filter((b) => b.row.reading_status === "third_only").map((b) => stripRecord(b.row));
  ensure(thirdOnly.length === EXPECTED.dpwh.third_only && rs.allocation_delta_php === EXPECTED.dpwh.reading_delta, "dpwh reading delta drifted");
  ensure(rs.third.operations_including_projects - rs.second.operations_including_projects === rs.allocation_delta_php, "reading delta does not tie");
  // Agency-level printed controls per reading, verbatim from the workbench's
  // reading comparison. The deltas must tie to its control_deltas_php block.
  const printedControls = READING_CONTROL_LABELS.map(([id, label]) => {
    const second = rs.second[id] ?? null;
    const third = rs.third[id] ?? null;
    const delta = second != null && third != null ? third - second : null;
    ensure(rs.control_deltas_php?.[id] == null || rs.control_deltas_php[id] === delta, `reading control ${id} delta does not tie to the source`);
    return { id, label, second_php: second, third_php: third, delta_php: delta };
  });
  const readings = {
    second_php: rs.second.operations_including_projects, third_php: rs.third.operations_including_projects, delta_php: rs.allocation_delta_php,
    status_counts: rs.status_counts, third_only: thirdOnly, changed_controls: controls.filter((c) => c.reading_delta_php),
    printed_controls: printedControls,
  };

  const meta: HgabDatasetMeta = {
    key: "dpwh", label: "DPWH national infrastructure", short: "DPWH", agency: "Department of Public Works and Highways", dept_id: "18",
    summary: "Roads, bridges, flood control and public buildings that DPWH would build or repair in 2027, listed project by project in the NEP and in the House bill.",
    one_row: "One named project, as each document lists it.",
    caveats: [
      "Only the project lists are compared. DPWH's staff costs, office running costs and a few non-project items are not included.",
      "Foreign-assisted projects are compared as one group.",
    ],
    grain: "Named project allocation with chainage, region and implementing office (grouped repeated House keys stay one row and count their members)",
    scope: "DPWH operations allocations published in NEP Volume II-B and House Bill 10858 Volume I-C, local and foreign-assisted, compared at the third reading; GAS, support to operations (personnel services and MOOE) and automatic appropriations sit outside the compared population, so agency new appropriations are broader. Foreign-assisted projects are carried under a single PAP control and program group.",
    totals, counts, printed, bridge, documents: { nep: [DOC.nepIIB], house: [DOC.ic3, DOC.ic2, DOC.ib3, DOC.ib2] },
    controls_label: "Program totals", has_readings: true, has_map: true,
  };
  const top: Partial<Record<BridgeGroup, ProjectRow[]>> = {};
  for (const g of BRIDGE_ORDER) top[g] = topBy(built, g);
  return { meta, summary: { dataset: meta, controls, dims, top, readings }, rows: built.map((b) => b.row), docPages };
}

// ---------------------------------------------------------------------------
// Annexes: FMR and NIA share the workbench shape {stages.{house,nep}.projects, comparison[]}
// ---------------------------------------------------------------------------

interface AnnexSource { source_pdf?: string; pdf_page?: number; printed_page?: number | null; row_id?: string }
interface AnnexProject {
  id: string; stage: string; title: string; amount_php: number; source: AnnexSource; region?: string; region_key?: string;
  status?: string; review_flags?: unknown[]; segment_count?: number; path_labels?: string[];
  subprogram_key?: string; subprogram_label?: string; program_group?: string; [k: string]: unknown;
}
interface AnnexComparison {
  id: string; status: "paired" | "house_only" | "nep_only"; method: string | null; nep_id: string | null; house_id: string | null;
  delta_php: number | null; ambiguous_title?: boolean; strict_status?: string; variant_mark_kind?: string | null;
  variant_mark?: { mark: string; counterpart_ids: string[] } | null; subprogram_key?: string; region_key?: string;
}
interface AnnexStage {
  projects: AnnexProject[]; root: { printed_amount_php?: number; amount_php?: number; source?: AnnexSource };
  audit_summary: { reading_comparison_identical_pages?: number; reading_comparison_total_pages?: number; grand_total?: number; control_total?: number };
  metadata?: { source_pdf_pages?: [number, number] };
}
interface AnnexWorkbench {
  schema_version: number; stages: { house: AnnexStage; nep: AnnexStage }; comparison: AnnexComparison[];
  comparison_summary: { delta_php: number; counts: Record<string, number> }; build_note?: string;
  regions?: Array<{ id: string; label: string; nep_php: number; house_php: number; nep_count: number; house_count: number; nep_source?: AnnexSource; house_source?: AnnexSource }>;
  subprogram_controls?: Array<{ key: string; label: string; program_group: string; house_php: number; nep_php: number; house_count: number; nep_count: number; house_source?: AnnexSource; nep_source?: AnnexSource }>;
}
const NIA_UNRESOLVED = new Set(["repeated_title", "location_variant", "exact_variant", "spelling_variant"]);

function traceFor(status: AnnexComparison["status"], house: number | null, nep: number | null): string {
  if (status === "house_only") return "house_only_candidate";
  if (status === "nep_only") return "nep_only_candidate";
  ensure(house != null && nep != null, "paired annex row missing a side");
  return house === nep ? "amount_same" : house > nep ? "candidate_increase" : "candidate_decrease";
}
function readingIdentity(stage: AnnexStage, key: string): number {
  const a = stage.audit_summary;
  ensure(a.reading_comparison_identical_pages && a.reading_comparison_identical_pages === a.reading_comparison_total_pages,
    `${key}: House annex text differs between readings`);
  return a.reading_comparison_total_pages ?? 0;
}

function buildAnnex(key: "fmr" | "nia", data: AnnexWorkbench, nepDoc: string, mainWs: MainWorkspace): { meta: HgabDatasetMeta; summary: DatasetSummary; rows: OutRow[]; docPages: Record<string, number[]> } {
  ensure(data.schema_version === 1, `${key}: unsupported workbench schema`);
  const index = { house: new Map(data.stages.house.projects.map((p) => [p.id, p])), nep: new Map(data.stages.nep.projects.map((p) => [p.id, p])) };
  const subLabel = new Map((data.subprogram_controls ?? []).map((c) => [c.key, c.label]));
  const identicalPages = readingIdentity(data.stages.house, key);
  const docPages: Record<string, number[]> = { [DOC.ib2]: [], [nepDoc]: [] };

  const built: Built[] = data.comparison.map((c) => {
    const house = c.house_id ? index.house.get(c.house_id) ?? null : null;
    const nep = c.nep_id ? index.nep.get(c.nep_id) ?? null : null;
    ensure((c.status === "paired" && house && nep) || (c.status === "house_only" && house && !nep) || (c.status === "nep_only" && nep && !house), `${key}: invalid comparison membership ${c.id}`);
    const lead = (house ?? nep) as AnnexProject;
    const h = intOrNull(house?.amount_php), n = intOrNull(nep?.amount_php);
    const flags: string[] = [];
    if (c.method) flags.push(`method:${c.method}`);
    if (c.ambiguous_title) flags.push("ambiguous_title");
    if (key === "fmr" && (house?.status === "needs_review" || nep?.status === "needs_review")) flags.push("coordinate_review");
    if (key === "nia") {
      if (c.strict_status && c.strict_status !== c.status) flags.push(`strict:${c.strict_status}`);
      if (c.variant_mark_kind && c.variant_mark_kind !== "no_counterpart") flags.push(`near_miss:${c.variant_mark_kind}`);
      if (c.status !== "paired" && c.variant_mark_kind && NIA_UNRESOLVED.has(c.variant_mark_kind)) flags.push("unresolved");
    }
    const housePage = intOrNull(house?.source?.pdf_page), nepPage = intOrNull(nep?.source?.pdf_page);
    if (housePage) docPages[DOC.ib2].push(housePage);
    if (nepPage) docPages[nepDoc].push(nepPage);
    const program = key === "fmr" ? lead.path_labels?.[0] ?? null : subLabel.get(c.subprogram_key ?? lead.subprogram_key ?? "") ?? lead.subprogram_label ?? null;
    const pap = key === "nia" ? lead.program_group ?? null : null;
    const region = key === "fmr" ? strOrNull(lead.region) : null;
    const row: OutRow = {
      id: c.id, dataset: key, title: lead.title, program, pap, region, office: null, office_kind: null, zone: null,
      trace: traceFor(c.status, h, n), house_match: c.status === "paired" ? c.method : null, reading_status: null, api_presence: null, confidence: null,
      nep_php: n, hgab2_php: h, hgab3_php: h, api_php: null, delta_php: h != null && n != null ? h - n : null,
      nep_page: nepPage, hgab2_page: housePage, hgab3_page: null,
      nep_doc: nep ? nepDoc : null, hgab2_doc: house ? DOC.ib2 : null, hgab3_doc: null,
      length_m: null, flags: flags.join(","), suggestions: 0,
      search_text: searchText([lead.title, program, pap, region, null]),
      record_json: JSON.stringify({ comparison: c, house, nep }),
    };
    return { row, group: groupOf(h, n, false), house: h, nep: n, delta: h != null && n != null ? h - n : 0 };
  });
  for (const side of ["house", "nep"] as const) {
    const ids = built.flatMap((b) => (side === "house" ? b.row.hgab2_php : b.row.nep_php) != null ? [b.row.id] : []);
    ensure(ids.length === data.stages[side].projects.length, `${key}: ${side} rows not covered exactly once`);
  }
  const bridge = bridgeOf(built, "hgab2");
  assertBridgeMatches(key, bridge, mainWs);
  const houseTotal = sum(data.stages.house.projects, (p) => p.amount_php), nepTotal = sum(data.stages.nep.projects, (p) => p.amount_php);
  const exp = EXPECTED[key];
  ensure(houseTotal === exp.house && nepTotal === exp.nep, `${key}: stage totals drifted (${houseTotal} / ${nepTotal})`);
  ensure(data.stages.house.projects.length === exp.counts.house && data.stages.nep.projects.length === exp.counts.nep, `${key}: stage counts drifted`);
  // Printed grand total: FMR carries it on the root node, NIA's NEP side in its audit summary.
  const rootPrinted = (s: AnnexStage) => s.root.printed_amount_php ?? s.root.amount_php ?? s.audit_summary.grand_total ?? s.audit_summary.control_total ?? null;
  ensure(rootPrinted(data.stages.house) === houseTotal && rootPrinted(data.stages.nep) === nepTotal, `${key}: printed root differs from ledger (${rootPrinted(data.stages.house)} / ${rootPrinted(data.stages.nep)})`);

  const controls: ControlRow[] = [];
  const dims: Partial<Record<DimKey, DimRow[]>> = {};
  if (key === "fmr") {
    for (const r of data.regions ?? []) {
      controls.push({
        id: r.id, label: r.label, group: null, nep_php: r.nep_php, hgab2_php: r.house_php, hgab3_php: r.house_php, api_php: null,
        delta_php: r.house_php - r.nep_php, reading_delta_php: null, nep_page: intOrNull(r.nep_source?.pdf_page),
        house_pages: r.house_source?.pdf_page ? [r.house_source.pdf_page] : [],
      });
    }
    dims.region = (data.regions ?? []).map((r) => ({ label: r.label, nep_php: r.nep_php, house_php: r.house_php, nep_records: r.nep_count, house_records: r.house_count }));
  } else {
    for (const c of data.subprogram_controls ?? []) {
      controls.push({
        id: c.key, label: c.label, group: c.program_group, nep_php: c.nep_php, hgab2_php: c.house_php, hgab3_php: c.house_php, api_php: null,
        delta_php: c.house_php - c.nep_php, reading_delta_php: null, nep_page: intOrNull(c.nep_source?.pdf_page),
        house_pages: c.house_source?.pdf_page ? [c.house_source.pdf_page] : [],
      });
    }
    dims.program = (data.subprogram_controls ?? []).map((c) => ({ label: c.label, nep_php: c.nep_php, house_php: c.house_php, nep_records: c.nep_count, house_records: c.house_count }));
  }
  ensure(sum(controls, (c) => c.nep_php) === nepTotal && sum(controls, (c) => c.hgab2_php) === houseTotal, `${key}: controls do not sum to stage totals`);
  for (const p of (data.regions ?? []).concat()) void p;

  const housePages = data.stages.house.metadata?.source_pdf_pages;
  const scopeBase = key === "fmr"
    ? "Locally funded farm-to-market road annex (DA activity 310203206315000) as published in the NEP schedule and House Bill 10858 Volume I-B; excludes FMR planning and monitoring and the bridges activities."
    : "The six detailed irrigation sub-programs of the NIA annex (agency 35-005) in the NEP schedule and House Bill 10858 Volume I-B; excludes the agency-only CARP row and the wider NIA appropriation.";
  const meta: HgabDatasetMeta = {
    key, label: key === "fmr" ? "DA farm-to-market roads" : "NIA irrigation", short: key.toUpperCase(),
    agency: key === "fmr" ? "Department of Agriculture" : "National Irrigation Administration", dept_id: key === "fmr" ? "05" : "35",
    summary: key === "fmr"
      ? "Farm-to-market roads that the Department of Agriculture would fund in 2027, listed road by road in both documents."
      : "Irrigation projects that the National Irrigation Administration would build or repair in 2027, listed under six programs in both documents.",
    one_row: key === "fmr" ? "One farm-to-market road project." : "One irrigation project.",
    caveats: key === "fmr"
      ? [
        "Road planning and the bridges program are listed elsewhere in the budget and are not included here.",
        "The House list is identical at second and third reading.",
      ]
      : [
        "Only the six project programs are listed; NIA's wider budget is not included.",
        "The House list is identical at second and third reading.",
      ],
    grain: key === "fmr" ? "One FMR project allocation as published, counted once across its coordinate segments" : "One irrigation project allocation as published, under one of six sub-programs",
    scope: `${scopeBase} The House side is the second-reading Volume I-B annex (PDF pages ${housePages?.[0]}–${housePages?.[1]}), verified text-identical to the third-reading copy across all ${identicalPages} pages, so the second- and third-reading versions of the House bill carry the same amounts.`,
    totals: { nep_php: nepTotal, hgab2_php: houseTotal, hgab3_php: houseTotal, api_php: null },
    counts: { nep: data.stages.nep.projects.length, hgab2: data.stages.house.projects.length, hgab3: data.stages.house.projects.length, api: null },
    printed: null, bridge, documents: { nep: [nepDoc], house: [DOC.ib2] },
    controls_label: key === "fmr" ? "Regions" : "Sub-programs", has_readings: false, has_map: key === "fmr",  // NIA prints no region or coordinates; its Map tab says so
  };
  const top: Partial<Record<BridgeGroup, ProjectRow[]>> = {};
  for (const g of BRIDGE_ORDER) top[g] = topBy(built, g);
  return { meta, summary: { dataset: meta, controls, dims, top, readings: null }, rows: built.map((b) => b.row), docPages };
}

// ---------------------------------------------------------------------------
// HFEP — funding-column record grain (overviewSummary.js hfepSummary + hfepModel.js)
// ---------------------------------------------------------------------------

type HfepColumn = "infrastructure" | "medical_equipment" | "motor_vehicle";
const COMPONENT_COLUMNS: readonly HfepColumn[] = ["infrastructure", "medical_equipment", "motor_vehicle"];
const COLUMN_LABELS: Record<HfepColumn | "total", string> = { infrastructure: "Infrastructure", medical_equipment: "Medical equipment", motor_vehicle: "Motor vehicle", total: "Total" };
interface HfepFacility {
  id: string; stage: string; title: string; path_labels?: string[]; parent_id?: string;
  amounts_php: Partial<Record<HfepColumn | "total", number | null>>; amount_lineage?: Array<{ column?: string; rule?: string }>;
  source: AnnexSource; [k: string]: unknown;
}
interface HfepNode {
  id: string; label: string; amounts_php: Partial<Record<HfepColumn | "total", number | null>>; source?: AnnexSource;
  parent_id?: string; child_ids?: string[]; facility_ids?: string[];
}
interface HfepStage {
  facilities: HfepFacility[]; categories: HfepNode[]; subcategories: HfepNode[]; regions: HfepNode[]; provinces: HfepNode[]; root: HfepNode; grand_total: HfepNode;
  facility_ledger: Record<string, number>; annex_control: Record<string, number>;
  audit_summary: { reading_comparison_identical_pages?: number; reading_comparison_total_pages?: number; facilities?: number };
  agency_check?: { mooe_php?: number; capital_outlay_php?: number; total_php?: number };
  printed_defects?: Array<{ node_id: string; label: string; column: string; printed_php: number; facility_sum_php: number; difference_php: number; documented_defect: string }>;
}
interface HfepWorkbench {
  schema_version: number; stages: { house: HfepStage; nep: HfepStage };
  comparison: { pairs: Array<{ house_id: string; nep_id: string; similarity: number }>; column_totals: Record<string, { house_php: number; nep_php: number; difference_php: number }>; counts: { pairs: number; house_only: number; nep_only: number } };
}
type HfepEvent = "same" | "revised" | "added" | "dropped" | "unmatched";
interface HfepRecord {
  id: string; facility_id: string; title: string; column: HfepColumn; column_label: string; side: "house" | "nep"; event: HfepEvent;
  house_value: number | null; nep_value: number | null; difference: number | null; similarity: number | null;
  region: string | null; province: string | null; category: string | null; subcategory: string | null; pair_id: string | null;
}

/** hfepModel.js recordColumnAmount(): derived zero cells are blank cells, not records. */
function recordColumnAmount(f: HfepFacility, col: HfepColumn): number | null {
  const amount = f.amounts_php?.[col] ?? null;
  return amount === 0 && f.amount_lineage?.some((s) => s.column === col && s.rule === "derived_from_row_identity_total_minus_components") ? null : amount;
}
/** hfepModel.js buildStageIndex()/facilityScope(): walk the printed hierarchy by node kind, not by path position. */
type HfepScopeKind = "category" | "subcategory" | "region" | "province";
interface HfepScope { category: string | null; subcategory: string | null; region: string | null; province: string | null }
function scopeIndex(stage: HfepStage): Map<string, { kind: HfepScopeKind | "root"; label: string; parent: string | null }> {
  const m = new Map<string, { kind: HfepScopeKind | "root"; label: string; parent: string | null }>();
  m.set(stage.root.id, { kind: "root", label: stage.root.label, parent: null });
  for (const c of stage.categories) m.set(c.id, { kind: "category", label: c.label, parent: stage.root.id });
  for (const s of stage.subcategories) m.set(s.id, { kind: "subcategory", label: s.label, parent: s.parent_id ?? null });
  for (const r of stage.regions) m.set(r.id, { kind: "region", label: r.label, parent: r.parent_id ?? null });
  for (const p of stage.provinces) m.set(p.id, { kind: "province", label: p.label, parent: p.parent_id ?? null });
  return m;
}
function facilityScope(index: ReturnType<typeof scopeIndex>, f: HfepFacility): HfepScope {
  const scope: HfepScope = { category: null, subcategory: null, region: null, province: null };
  let id: string | null = f.parent_id ?? null;
  for (let guard = 0; id && guard < 10; guard++) {
    const node = index.get(id);
    if (!node) break;
    if (node.kind !== "root") scope[node.kind] = node.label;
    id = node.parent;
  }
  return scope;
}
function hfepNepPage(f: HfepFacility | HfepNode): number | null {
  const page = intOrNull(f.source?.pdf_page);
  if (page == null) return null;
  const m = /^nep_hfep:p(\d+):/.exec(f.id);
  const excerpt = page - HFEP_PAGE_OFFSET;
  ensure(!m || Number(m[1]) === excerpt, `HFEP page mapping broke for ${f.id}`);
  return excerpt;
}

function buildHfep(data: HfepWorkbench, mainWs: MainWorkspace): { meta: HgabDatasetMeta; summary: DatasetSummary; rows: OutRow[]; docPages: Record<string, number[]> } {
  ensure(data.schema_version === 1, "hfep: unsupported workbench schema");
  const H = data.stages.house, N = data.stages.nep;
  const houseById = new Map(H.facilities.map((f) => [f.id, f])), nepById = new Map(N.facilities.map((f) => [f.id, f]));
  const identicalPages = readingIdentity(H as unknown as AnnexStage, "hfep");
  const scopes = { house: scopeIndex(H), nep: scopeIndex(N) };
  const scopeOf = (f: HfepFacility): HfepScope => facilityScope(f.stage === "house" ? scopes.house : scopes.nep, f);

  // hfepModel.js comparisonIndex() + lineItemRecords(), ported.
  const records: HfepRecord[] = [];
  const push = (f: HfepFacility, column: HfepColumn, side: "house" | "nep", event: HfepEvent, counterpart: HfepFacility | null, pair: { house: HfepFacility; nep: HfepFacility; similarity: number; hv: number | null; nv: number | null } | null) => {
    const sc = scopeOf(pair ? pair.house : f);
    records.push({
      id: `${f.id}|${column}`, facility_id: f.id, title: f.title, column, column_label: COLUMN_LABELS[column], side, event,
      house_value: event === "revised" || event === "same" ? pair!.hv : side === "house" || event === "dropped" ? recordColumnAmount(f, column) : null,
      nep_value: event === "revised" || event === "same" ? pair!.nv : side === "nep" || event === "added" ? recordColumnAmount(f, column) : null,
      difference: (event === "revised" || event === "same") && pair ? (pair.nv ?? 0) - (pair.hv ?? 0) : null,
      similarity: pair?.similarity ?? null, ...sc, pair_id: pair ? `${pair.house.id}~${pair.nep.id}` : null,
    });
    void counterpart;
  };
  const pairedHouse = new Set<string>(), pairedNep = new Set<string>();
  const pairOf = new Map<string, { house_id: string; nep_id: string; similarity: number }>();
  for (const p of data.comparison.pairs) {
    const house = houseById.get(p.house_id), nep = nepById.get(p.nep_id);
    ensure(house && nep, `hfep pair references unknown facility ${p.house_id} / ${p.nep_id}`);
    pairedHouse.add(house.id); pairedNep.add(nep.id);
    for (const column of COMPONENT_COLUMNS) {
      const hv = recordColumnAmount(house, column), nv = recordColumnAmount(nep, column);
      const event: HfepEvent | "none" = hv == null && nv == null ? "none" : hv == null ? "added" : nv == null ? "dropped" : hv === nv ? "same" : "revised";
      if (event === "none") continue;
      const pair = { house, nep, similarity: p.similarity, hv, nv };
      if (event === "added") push(nep, column, "nep", event, house, pair);
      else push(house, column, "house", event, nep, pair);
      pairOf.set(`${(event === "added" ? nep : house).id}|${column}`, p);
    }
  }
  for (const f of H.facilities) if (!pairedHouse.has(f.id)) for (const c of COMPONENT_COLUMNS) if (recordColumnAmount(f, c) != null) push(f, c, "house", "unmatched", null, null);
  for (const f of N.facilities) if (!pairedNep.has(f.id)) for (const c of COMPONENT_COLUMNS) if (recordColumnAmount(f, c) != null) push(f, c, "nep", "unmatched", null, null);
  ensure(new Set(records.map((r) => r.id)).size === records.length, "hfep record ids collide");

  // Source totals at record grain must equal the facility ledgers (hfepSummary).
  for (const [side, stage] of [["house", H], ["nep", N]] as const) {
    const components = stage.facilities.flatMap((f) => COMPONENT_COLUMNS.map((c) => recordColumnAmount(f, c))).filter((v): v is number => v != null);
    const represented = records.filter((r) => r[`${side}_value`] != null);
    ensure(sum(components, (v) => v) === stage.facility_ledger.total, `hfep ${side} components do not reconcile to ledger`);
    ensure(represented.length === components.length && sum(represented, (r) => r[`${side}_value`]) === stage.facility_ledger.total, `hfep ${side} record partition`);
  }

  const docPages: Record<string, number[]> = { [DOC.ib2]: [], [DOC.nepHfep]: [] };
  const built: Built[] = records.map((r) => {
    const pair = pairOf.get(r.id) ?? null;
    const house = r.side === "house" || r.event === "dropped" ? houseById.get(r.facility_id) ?? null : pair ? houseById.get(pair.house_id) ?? null : null;
    const nep = r.side === "nep" || r.event === "added" ? nepById.get(r.facility_id) ?? null : pair ? nepById.get(pair.nep_id) ?? null : null;
    const h = r.house_value, n = r.nep_value;
    // Booked movement, House − NEP; a blank cell on a paired facility counts as 0 (hfepSummary delta()).
    const booked = r.event === "revised" || r.event === "same" ? (h ?? 0) - (n ?? 0) : r.event === "added" ? -(n ?? 0) : r.event === "dropped" ? (h ?? 0) : 0;
    const trace = r.event === "unmatched" ? (r.side === "house" ? "house_only_candidate" : "nep_only_candidate")
      : r.event === "same" ? "amount_same" : booked > 0 ? "candidate_increase" : "candidate_decrease";
    const group: BridgeGroup = r.event === "unmatched" ? (r.side === "house" ? "house_only" : "nep_only")
      : r.event === "same" ? "unchanged" : booked > 0 ? "increased" : "decreased";
    const flags: string[] = [];
    if (r.event === "added") flags.push("column_added");
    if (r.event === "dropped") flags.push("column_dropped");
    const lead = (r.side === "house" ? house : nep) ?? house ?? nep;
    ensure(lead, `hfep record ${r.id} has no facility`);
    const housePage = house ? intOrNull(house.source?.pdf_page) : null, nepPage = nep ? hfepNepPage(nep) : null;
    if (housePage) docPages[DOC.ib2].push(housePage);
    if (nepPage) docPages[DOC.nepHfep].push(nepPage);
    const sc = scopeOf(lead);
    const row: OutRow = {
      id: r.id, dataset: "hfep", title: lead.title, program: sc.category, pap: r.column_label, region: sc.region, office: null, office_kind: null, zone: null,
      trace, house_match: pair ? "title_similarity" : null, reading_status: null, api_presence: null, confidence: r.similarity,
      nep_php: n, hgab2_php: h, hgab3_php: h, api_php: null,
      delta_php: r.event === "unmatched" ? null : booked,
      nep_page: nepPage, hgab2_page: housePage, hgab3_page: null,
      nep_doc: nep ? DOC.nepHfep : null, hgab2_doc: house ? DOC.ib2 : null, hgab3_doc: null,
      length_m: null, flags: flags.join(","), suggestions: 0,
      search_text: searchText([lead.title, sc.category, r.column_label, sc.region, sc.province]),
      record_json: JSON.stringify({ record: r, house, nep, pair }),
    };
    return { row, group, house: h, nep: n, delta: booked };
  });
  const bridge = bridgeOf(built, "hgab2");
  assertBridgeMatches("hfep", bridge, mainWs);
  ensure(H.facility_ledger.total === EXPECTED.hfep.house && H.annex_control.total === EXPECTED.hfep.house && N.annex_control.total === EXPECTED.hfep.nep_printed && N.facility_ledger.total === EXPECTED.hfep.nep_ledger, "hfep totals drifted");
  ensure(bridge.net_php === H.facility_ledger.total - N.facility_ledger.total, "hfep bridge net must equal the ledger difference");
  ensure(H.facilities.length === EXPECTED.hfep.facilities.house && N.facilities.length === EXPECTED.hfep.facilities.nep, "hfep facility counts drifted");

  // Controls: printed per-column annex controls, then the printed category rows joined by their printed number.
  const controls: ControlRow[] = [];
  for (const col of ["infrastructure", "medical_equipment", "motor_vehicle", "total"] as const) {
    const t = data.comparison.column_totals[col];
    controls.push({
      id: `column:${col}`, label: COLUMN_LABELS[col], group: "Funding columns, as published", nep_php: t.nep_php, hgab2_php: t.house_php, hgab3_php: t.house_php,
      api_php: null, delta_php: t.house_php - t.nep_php, reading_delta_php: null, nep_page: hfepNepPage(N.grand_total), house_pages: H.grand_total.source?.pdf_page ? [H.grand_total.source.pdf_page] : [],
    });
  }
  const catNo = (label: string) => /^(\d+)\./.exec(label)?.[1] ?? label;
  const nepCats = new Map(N.categories.map((c) => [catNo(c.label), c]));
  const seen = new Set<string>();
  for (const c of H.categories) {
    const n = nepCats.get(catNo(c.label)) ?? null;
    if (n) seen.add(catNo(c.label));
    const nepTotal = n?.amounts_php.total ?? null, houseTotal = c.amounts_php.total ?? null;
    controls.push({
      id: `category:${catNo(c.label)}`, label: n && n.label !== c.label ? `${c.label} (NEP: ${n.label})` : c.label, group: "Categories, as published",
      nep_php: nepTotal, hgab2_php: houseTotal, hgab3_php: houseTotal, api_php: null,
      delta_php: nepTotal != null && houseTotal != null ? houseTotal - nepTotal : null, reading_delta_php: null,
      nep_page: n ? hfepNepPage(n) : null, house_pages: c.source?.pdf_page ? [c.source.pdf_page] : [],
    });
  }
  for (const n of N.categories) {
    if (seen.has(catNo(n.label))) continue;
    controls.push({
      id: `category:${catNo(n.label)}`, label: n.label, group: "Categories, as published", nep_php: n.amounts_php.total ?? null, hgab2_php: null, hgab3_php: null,
      api_php: null, delta_php: null, reading_delta_php: null, nep_page: hfepNepPage(n), house_pages: [],
    });
  }

  // Dims at record grain, each side under its own recorded label.
  const dimOf = (pick: (f: HfepFacility, r: HfepRecord) => string | null): DimRow[] => {
    const m = new Map<string, DimRow>();
    const tally = (label: string, side: "house" | "nep", v: number) => {
      const e = m.get(label) ?? { label, nep_php: 0, house_php: 0, nep_records: 0, house_records: 0 };
      e[`${side}_php`] += v; e[`${side}_records`] += 1; m.set(label, e);
    };
    for (const b of built) {
      const r = (JSON.parse(b.row.record_json) as { record: HfepRecord }).record;
      const pair = pairOf.get(r.id) ?? null;
      const hf = r.house_value != null ? houseById.get(r.side === "house" ? r.facility_id : pair?.house_id ?? "") : undefined;
      const nf = r.nep_value != null ? nepById.get(r.side === "nep" ? r.facility_id : pair?.nep_id ?? "") : undefined;
      if (hf && r.house_value != null) tally(pick(hf, r) ?? "No recorded label", "house", r.house_value);
      if (nf && r.nep_value != null) tally(pick(nf, r) ?? "No recorded label", "nep", r.nep_value);
    }
    return [...m.values()].sort((a, b) => Math.abs(b.house_php - b.nep_php) - Math.abs(a.house_php - a.nep_php) || a.label.localeCompare(b.label));
  };
  const dims: Partial<Record<DimKey, DimRow[]>> = {
    region: dimOf((f) => scopeOf(f).region), program: dimOf((f) => scopeOf(f).category), pap: dimOf((_f, r) => r.column_label),
  };
  for (const [k, d] of Object.entries(dims)) {
    ensure(sum(d, (x) => x.house_php) === H.facility_ledger.total && sum(d, (x) => x.nep_php) === N.facility_ledger.total, `hfep dim ${k} does not conserve ledgers`);
  }
  const mw = mainWs as MainWorkspace & { sources: { house: { count: number }; nep: { count: number } } };
  ensure(records.filter((r) => r.house_value != null).length === mw.sources.house.count && records.filter((r) => r.nep_value != null).length === mw.sources.nep.count, "hfep record counts differ from main_overview");

  const meta: HgabDatasetMeta = {
    key: "hfep", label: "DOH Health Facilities Enhancement Program", short: "HFEP", agency: "Department of Health", dept_id: "13",
    summary: "Hospitals, health centres and other facilities that the Department of Health would build, repair or equip in 2027 under its Health Facilities Enhancement Program.",
    one_row: "One facility's budget line for building works, medical equipment or vehicles. A facility can have up to three lines.",
    caveats: [
      "Only construction, equipment and vehicle budgets are listed. ₱67.2M for running costs is not included.",
      "The NEP list adds up to ₱140,000 less than the total published on it, an error in the published list noted by the source. These pages use the sum of the lines.",
      "The House list is identical at second and third reading.",
    ],
    grain: "One funding-column cell (Infrastructure, Medical equipment or Motor vehicle) of one facility, as published; facility totals are controls, so a facility can appear as up to three rows",
    scope: `HFEP capital outlays (DOH activity 350202100002000) as published in the NEP Volume II-A annex and House Bill 10858 Volume I-B; both schedules include national and LGU facilities, and the ₱67,173,000 MOOE of the activity sits outside the annex. Totals are the facility ledgers the bridge is measured on: the NEP ledger is ₱14,472,519,000 while the NEP annex control as published is ₱14,472,659,000, ₱140,000 higher because of a documented error in a Metro Manila medical-equipment line of the published list (the published control is kept in the controls table); the House ledger and published control agree at ₱10,021,659,000. The House side is the second-reading Volume I-B annex (PDF pages 877–893), verified text-identical to the third-reading copy across all ${identicalPages} pages.`,
    totals: { nep_php: N.facility_ledger.total, hgab2_php: H.facility_ledger.total, hgab3_php: H.facility_ledger.total, api_php: null },
    counts: { nep: mw.sources.nep.count, hgab2: mw.sources.house.count, hgab3: mw.sources.house.count, api: null },
    printed: { nep_new_appropriations_php: N.agency_check?.total_php ?? null, house_new_appropriations_php: H.agency_check?.total_php ?? null },
    bridge, documents: { nep: [DOC.nepHfep], house: [DOC.ib2] }, controls_label: "Categories", has_readings: false, has_map: true,
  };
  const top: Partial<Record<BridgeGroup, ProjectRow[]>> = {};
  for (const g of BRIDGE_ORDER) top[g] = topBy(built, g);
  return { meta, summary: { dataset: meta, controls, dims, top, readings: null }, rows: built.map((b) => b.row), docPages };
}

// ---------------------------------------------------------------------------
// Reconciliation against our FY2027 NEP tree (docs/dpwh-nep-hb-2027-review.md)
// ---------------------------------------------------------------------------

interface OurSummary {
  department: { amount: number }; expense_classes: Array<{ code: string; amount: number }>; fund_subcategories: Array<{ code: string; description: string; amount: number }>;
}
interface OurFpap { fpap_code: string; description: string; prexc_level: number; program_code: string; agency_id: string; years: Record<string, { amount: number }> }
interface OurExpense { fpap_id: string; expense_code: string; years: Record<string, { amount: number }> }
interface Envelope<T> { metadata: { scale?: string }; data: T[] }

const norm = (s: string) => s.toLowerCase().normalize("NFKC").replace(/[^a-z0-9]+/g, " ").trim();
const toPesos = (thousands: number) => Math.round(thousands * 1000);

function reconcile(nepDir: string, src: string, built: Partial<Record<DatasetKey, { meta: HgabDatasetMeta }>>): ReconciliationRow[] {
  const rows: ReconciliationRow[] = [];
  const add = (dataset: DatasetKey, check: string, ours: number | null, theirs: number | null, status: ReconciliationRow["status"] | null, note: string) => {
    const diff = ours != null && theirs != null ? ours - theirs : null;
    rows.push({ dataset, check, ours_php: ours, theirs_php: theirs, diff_php: diff, status: status ?? (diff === 0 ? "exact" : "mismatch"), note });
  };
  if (!existsSync(resolve(nepDir, "18/summary.json"))) {
    rows.push({ dataset: "dpwh", check: "FY2027 NEP tree", ours_php: null, theirs_php: null, diff_php: null, status: "mismatch", note: `${nepDir} not found — run npm run import:nep2027 first` });
    return rows;
  }
  const leaves = (dept: string) => readJson<Envelope<OurFpap>>(resolve(nepDir, dept, "fpaps.json")).data;

  // --- DPWH -----------------------------------------------------------------
  if (built.dpwh) {
    const ours = readJson<OurSummary>(resolve(nepDir, "18/summary.json"));
    const tree = readJson<{ summary: { total_php: number; expense_classes: Record<string, number>; program_totals_php: Record<string, number> } }>(resolve(src, "analysis/data/nep_2027_tree.json"));
    const srcProjects = readJson<{ pap_controls: Record<string, { id: string; page: number; amount_php: number }> }>(resolve(src, "analysis/data/nep_2027_source_projects.json"));
    const fund = (code: string) => ours.fund_subcategories.find((f) => f.code === code)?.amount ?? 0;
    const rlip = fund("10401102"), nbcdf = fund("10403389");
    add("dpwh", "DPWH total, without the two items released automatically (retirement premiums and the building-code fund)",
      ours.department.amount - rlip - nbcdf, tree.summary.total_php, null,
      `Our department total is ${peso(ours.department.amount)}; taking out the ${peso(rlip + nbcdf)} released automatically, without a vote, gives the source's figure (funds 10401102, 10403389).`);
    const cls = (code: string) => ours.expense_classes.find((e) => e.code === code)?.amount ?? null;
    const T = tree.summary.expense_classes;
    add("dpwh", "DPWH capital outlays (construction and equipment)", cls("6"), T["CAPITAL OUTLAYS"] ?? null, null, "Our construction and equipment budget against the source's total for the same (expense class 6).");
    const psDiff = (cls("1") ?? 0) - (T["Personnel Services"] ?? 0);
    add("dpwh", "DPWH staff costs (personnel services)", cls("1"), T["Personnel Services"] ?? null, psDiff === rlip ? "explained" : "mismatch", `Ours is higher by ${peso(rlip)}: the retirement and life insurance premiums, which are released automatically (fund 10401102).`);
    const mooeDiff = (cls("2") ?? 0) - (T["MAINTENANCE AND OTHER OPERATING EXPENSES"] ?? 0);
    add("dpwh", "DPWH office running costs (maintenance and other operating expenses)", cls("2"), T["MAINTENANCE AND OTHER OPERATING EXPENSES"] ?? null, mooeDiff === nbcdf ? "explained" : "mismatch", `Ours is higher by ${peso(nbcdf)}: the National Building Code Development Fund, which is released automatically (fund 10403389).`);

    const leaf = leaves("18").filter((r) => r.prexc_level === 7);
    const byPrefix = (prefixes: string[]) => toPesos(sum(leaf.filter((r) => prefixes.some((p) => r.fpap_code.startsWith(p))), (r) => r.years["2027"]?.amount));
    const P = tree.summary.program_totals_php;
    const programs: Array<[string, string[], string]> = [
      ["Asset Preservation Program", ["3101"], "PREXC 3101"], ["Network Development Program", ["3102"], "PREXC 3102"], ["Bridge Program", ["3103"], "PREXC 3103"],
      ["Flood Management Program", ["3201", "3202"], "PREXC 3201 + 3202"], ["Convergence and Special Support Program", ["3002"], "PREXC 3002"], ["Local Program", ["3001"], "PREXC 3001"],
    ];
    for (const [label, prefixes, note] of programs) add("dpwh", `Program total: ${label}`, byPrefix(prefixes), P[label] ?? null, null, `Our activities under this program, added up, against the source's program total (${note}).`);
    const gasDiff = byPrefix(["1"]) - (P["General Administration and Support"] ?? 0), stoDiff = byPrefix(["2"]) - (P["Support to Operations"] ?? 0);
    const autoOk = gasDiff + stoDiff === rlip + nbcdf;
    add("dpwh", "DPWH general administration and support", byPrefix(["1"]), P["General Administration and Support"] ?? null, autoOk ? "explained" : "mismatch",
      `Together with support to operations, ours is higher by ${peso(gasDiff + stoDiff)}: the two items released automatically, which our data counts under these two programs (funds 10401102, 10403389).`);
    add("dpwh", "DPWH support to operations", byPrefix(["2"]), P["Support to Operations"] ?? null, autoOk ? "explained" : "mismatch",
      `See general administration and support: the two items released automatically are spread across both programs, which together differ by ${peso(gasDiff + stoDiff)}.`);

    // 45 printed PAP controls vs our program groups (level-7 leaves grouped by program_code).
    const groups = new Map<string, { label: string; total: number; fap: number }>();
    const labelOf = new Map(leaves("18").map((r) => [r.fpap_code, r.description]));
    for (const r of leaf) {
      const g = groups.get(r.program_code) ?? { label: labelOf.get(r.program_code) ?? r.description, total: 0, fap: 0 };
      const amt = toPesos(r.years["2027"]?.amount ?? 0);
      g.total += amt;
      if (r.fpap_code[6] === "3") g.fap += amt; // Foreign-Assisted Project(s) leaves
      groups.set(r.program_code, g);
    }
    const ourByLabel = new Map<string, string[]>();
    for (const [code, g] of groups) ourByLabel.set(norm(g.label), [...(ourByLabel.get(norm(g.label)) ?? []), code]);
    const usedOurs = new Set<string>();
    const pending: Array<[string, number]> = [];
    for (const [label, ctl] of Object.entries(srcProjects.pap_controls)) {
      const codes = (ourByLabel.get(norm(label)) ?? []).filter((c) => !usedOurs.has(c));
      if (codes.length === 1) {
        const g = groups.get(codes[0])!; usedOurs.add(codes[0]);
        if (g.total === ctl.amount_php) add("dpwh", `Program line: ${label}`, g.total, ctl.amount_php, "exact", `Same amount in our data (program ${codes[0]}).`);
        else if (g.total - g.fap === ctl.amount_php) add("dpwh", `Program line: ${label}`, g.total, ctl.amount_php, "explained", `Our data adds ${peso(g.fap)} of foreign-assisted projects to the same line; the published total covers locally funded projects only (program ${codes[0]}).`);
        else add("dpwh", `Program line: ${label}`, g.total, ctl.amount_php, "mismatch", `Our amount differs, and the gap is not the foreign-assisted part (${peso(g.fap)}; program ${codes[0]}).`);
      } else pending.push([label, ctl.amount_php]);
    }
    // Labels that did not match: pair by unique amount, then explain regroupings by group sums.
    const stillPending: Array<[string, number]> = [];
    for (const [label, amount] of pending) {
      const hits = [...groups].filter(([code, g]) => !usedOurs.has(code) && (g.total === amount || g.total - g.fap === amount));
      if (hits.length === 1) {
        const [code, g] = hits[0]; usedOurs.add(code);
        add("dpwh", `Program line: ${label}`, g.total, amount, "explained", `Our data names this line "${g.label.replace(/\s+/g, " ").trim()}"; matched by amount${g.total !== amount ? ` net of ${peso(g.fap)} of foreign-assisted projects` : ""} (program ${code}).`);
      } else stillPending.push([label, amount]);
    }
    const leftover = [...groups].filter(([code, g]) => !usedOurs.has(code) && g.total > 0 && !/^[12]/.test(code));
    const leftoverSum = sum(leftover, ([, g]) => g.total), pendingSum = sum(stillPending, ([, a]) => a);
    for (const [label, amount] of stillPending) {
      add("dpwh", `Program line: ${label}`, null, amount, leftoverSum === pendingSum ? "explained" : "mismatch",
        `This published line has no single counterpart in our data; the ${stillPending.length} published lines without one (${peso(pendingSum)}) add up to the same total as ${leftover.length} of our programs (${peso(leftoverSum)}): ${leftover.map(([c, g]) => `${g.label.replace(/\s+/g, " ").trim()} (${c})`).join("; ")}.`);
    }
    add("dpwh", "Published program lines covered", Object.keys(srcProjects.pap_controls).length, 45, "info", `${rows.filter((r) => r.check.startsWith("Program line:")).length} program lines compared (counts, not pesos).`);
  }

  // --- FMR ------------------------------------------------------------------
  if (built.fmr) {
    const fmr = leaves("05").find((r) => r.fpap_code === "310203206315000" && r.prexc_level === 7);
    add("fmr", "Farm-to-market roads: our budget line for the program against the total of the source's list (DA activity 310203206315000)", fmr ? toPesos(fmr.years["2027"]?.amount ?? 0) : null, built.fmr.meta.totals.nep_php, null,
      "Our wider farm-to-market sub-program also pays for road planning and monitoring, which the list leaves out, so only the road-building line is compared.");
  }
  // --- HFEP -----------------------------------------------------------------
  if (built.hfep) {
    const exp = readJson<Envelope<OurExpense>>(resolve(nepDir, "13/expenses.json")).data.filter((e) => e.fpap_id.endsWith("-350202100002000"));
    const byClass = (code: string) => toPesos(sum(exp.filter((e) => e.expense_code === code), (e) => e.years["2027"]?.amount));
    const hfepWb = readJson<HfepWorkbench>(resolve(src, "other-analysis/data/hfep_workbench.json"));
    const printed = hfepWb.stages.nep.annex_control.total, ledger = hfepWb.stages.nep.facility_ledger.total;
    ensure(ledger === built.hfep.meta.totals.nep_php, "hfep totals.nep_php must be the facility ledger");
    add("hfep", "Health facilities: our construction and equipment budget against the total published on the NEP list (DOH activity 350202100002000)", byClass("6"), printed, null, "Our construction and equipment budget for the program against the grand total published on the list, not the sum of its lines (expense class 6).");
    add("hfep", "Health facilities: running costs, which the list does not cover (DOH activity 350202100002000)", byClass("2"), 67_173_000, byClass("2") === 67_173_000 ? "explained" : "mismatch", "The list covers construction, equipment and vehicles only; the program's ₱67,173,000 for running costs sits outside it, as the source documents.");
    add("hfep", "Health facilities: our construction and equipment budget against the sum of the list's lines (the figure these pages use)", byClass("6"), ledger, byClass("6") - ledger === 140_000 && printed - ledger === 140_000 ? "explained" : "mismatch",
      `Ours (${peso(byClass("6"))}) equals the published total but is ₱140,000 more than the sum of the lines (${peso(ledger)}), which these pages use; the source documents the gap as an error in a Metro Manila medical-equipment line of the published list.`);
  }
  // --- NIA ------------------------------------------------------------------
  if (built.nia) {
    const nia = leaves("35").filter((r) => r.agency_id === "35-005" && r.prexc_level === 7);
    const subs: Array<[string, string, number]> = [
      ["310101", "National Irrigation System", 4_662_231_000], ["310102", "Communal Irrigation System", 1_620_000_000], ["310106", "Other Irrigation Systems", 3_000_000_000],
      ["310202", "Establishment of Pump Irrigation", 7_915_950_000], ["310204", "Special Irrigation", 200_000_000], ["310205", "Extension/Expansion of Existing Irrigation Systems", 200_000_000],
    ];
    const theirs = readJson<AnnexWorkbench>(resolve(src, "analysis-nia/data/nia_workbench.json")).subprogram_controls ?? [];
    for (const [prefix, label, fallback] of subs) {
      const ours = toPesos(sum(nia.filter((r) => r.fpap_code.startsWith(prefix)), (r) => r.years["2027"]?.amount));
      const t = theirs.find((c) => norm(c.key).startsWith(norm(label).split(" ").slice(0, 2).join(" ")))?.nep_php ?? fallback;
      add("nia", `Irrigation program: ${label} (sub-program ${prefix})`, ours, t, null, `Our NIA activities under this program, added up, against the source's program total (agency 35-005, PREXC ${prefix}).`);
    }
    add("nia", "Irrigation: the six programs together", toPesos(sum(nia.filter((r) => subs.some(([p]) => r.fpap_code.startsWith(p))), (r) => r.years["2027"]?.amount)), built.nia.meta.totals.nep_php, null, "Sum of the six programs against the total of the source's list.");
  }
  return rows;
}

// ---------------------------------------------------------------------------
// Parquet
// ---------------------------------------------------------------------------

async function writeParquet(rows: OutRow[], dir: string): Promise<{ rows: number; bytes: number; columns: string[] }> {
  const tmp = resolve(dir, ".projects.ndjson"), parquet = resolve(dir, "projects.parquet");
  rmSync(tmp, { force: true }); rmSync(parquet, { force: true });
  const chunk: string[] = [];
  for (let i = 0; i < rows.length; i++) {
    chunk.push(JSON.stringify(rows[i]));
    if (chunk.length === 2000 || i === rows.length - 1) { appendFileSync(tmp, `${chunk.join("\n")}\n`); chunk.length = 0; }
  }
  const db = await DuckDBInstance.create(":memory:");
  const c = await db.connect();
  try {
    const columns = PROJECT_COLUMNS.map((k) => `${k}: '${COLUMN_TYPES[k]}'`).join(", ");
    await c.run(`CREATE TABLE p AS SELECT * FROM read_ndjson('${q(tmp)}', columns = {${columns}}, maximum_object_size = 268435456)`);
    await c.run(`COPY (SELECT ${PROJECT_COLUMNS.join(", ")} FROM p) TO '${q(parquet)}' (FORMAT PARQUET, COMPRESSION ZSTD)`);
    const n = Number((await c.runAndReadAll(`SELECT count(*) FROM read_parquet('${q(parquet)}')`)).getRows()[0][0]);
    const cols = (await c.runAndReadAll(`DESCRIBE SELECT * FROM read_parquet('${q(parquet)}')`)).getRows().map((r) => String(r[0]));
    ensure(n === rows.length, `parquet row count ${n} != ${rows.length}`);
    ensure(cols.join(",") === PROJECT_COLUMNS.join(","), `parquet columns differ: ${cols.join(",")}`);
    return { rows: n, bytes: statSync(parquet).size, columns: cols };
  } finally {
    c.closeSync(); db.closeSync(); rmSync(tmp, { force: true });
  }
}

// ---------------------------------------------------------------------------
// Documents
// ---------------------------------------------------------------------------

function range(pages: number[] | undefined): { from: number; to: number } | null {
  const p = (pages ?? []).filter((n) => Number.isFinite(n) && n > 0);
  return p.length ? { from: Math.min(...p), to: Math.max(...p) } : null;
}
function buildDocuments(src: string, used: Record<string, number[]>): HgabDocument[] {
  const info = (key: string) => {
    const path = resolve(src, DOC_SOURCES[key]);
    ensure(existsSync(path), `missing source PDF ${path}`);
    return { sha256: sha256(path), bytes: statSync(path).size };
  };
  const houseUrl = "https://www.congress.gov.ph/cso";
  const ibNote = "Page numbers are positions in this file, not the page numbers shown on the pages. This volume carries the DPWH program totals (the project list is in Volume I-C) and the lists of farm-to-market roads (pages 667–726), health facilities (877–893) and irrigation projects (896–941).";
  return [
    { key: DOC.ib2, title: "House Bill 10858, Volume I-B: program totals and the three project lists, second reading", stage: "house", reading: 2, volume: "I-B", pages: range(used[DOC.ib2]), ...info(DOC.ib2), source_url: houseUrl, notes: `${ibNote} The list pages are word-for-word identical in the third-reading copy, so list rows link to this copy.` },
    { key: DOC.ic2, title: "House Bill 10858, Volume I-C: DPWH project list, second reading", stage: "house", reading: 2, volume: "I-C", pages: range(used[DOC.ic2]), ...info(DOC.ic2), source_url: houseUrl, notes: "The DPWH project list as published for second reading. Page numbers are positions in this file. Project rows link here; program totals link to Volume I-B." },
    { key: DOC.ib3, title: "House Bill 10858, Volume I-B: program totals and the three project lists, third reading", stage: "house", reading: 3, volume: "I-B", pages: range(used[DOC.ib3]), ...info(DOC.ib3), source_url: houseUrl, notes: `${ibNote} The list pages are identical to the second-reading copy, at the same positions.` },
    { key: DOC.ic3, title: "House Bill 10858, Volume I-C: DPWH project list, third reading", stage: "house", reading: 3, volume: "I-C", pages: range(used[DOC.ic3]), ...info(DOC.ic3), source_url: houseUrl, notes: "The DPWH project list as published for third reading. Page numbers are positions in this file. Project rows link here; program totals link to Volume I-B." },
    { key: DOC.nepIIB, title: "NEP 2027, Volume II-B: DPWH", stage: "nep", reading: null, volume: "II-B", pages: range(used[DOC.nepIIB]), ...info(DOC.nepIIB), source_url: "https://www.dbm.gov.ph/wp-content/uploads/NEP2027/DPWH/DPWH.pdf", notes: "A 722-page scanned copy with machine-read text, the copy the source analysis worked from. Page numbers are positions in this file and do not match the DBM-published extract linked under Original." },
    { key: DOC.nepFmr, title: "NEP 2027: farm-to-market roads list, Department of Agriculture", stage: "nep", reading: null, volume: "Annex (NEP Volume I, page numbers 1511–1557 as shown on the pages)", pages: range(used[DOC.nepFmr]), ...info(DOC.nepFmr), source_url: null, notes: "A 47-page list supplied with the source analysis. Page numbers are positions in this file." },
    { key: DOC.nepNia, title: "NEP 2027: irrigation projects list, National Irrigation Administration", stage: "nep", reading: null, volume: "Annex", pages: range(used[DOC.nepNia]), ...info(DOC.nepNia), source_url: null, notes: "A 30-page scanned list with machine-read text. Page numbers are positions in this file." },
    { key: DOC.nepHfep, title: "NEP 2027, Volume II-A: health facilities list, Department of Health", stage: "nep", reading: null, volume: "II-A (PDF pages 727–739)", pages: range(used[DOC.nepHfep]), ...info(DOC.nepHfep), source_url: null, notes: `A 13-page extract of Volume II-A: its pages 1–13 are pages ${HFEP_PAGE_OFFSET + 1}–${HFEP_PAGE_OFFSET + 13} of the full volume (the page numbers shown on the pages: 719–731). Health-facility rows link to this extract's pages.` },
  ];
}

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------

async function main(): Promise<void> {
  const args = parseArgs();
  ensure(existsSync(args.src), `${args.src} not found`);
  const need = [
    "analysis/data/comparison_projects_2027.json", "analysis/data/comparison_overview_2027.json", "analysis/data/main_overview_2027.json",
    "other-analysis/data/fmr_workbench.json", "other-analysis/data/hfep_workbench.json", "analysis-nia/data/nia_workbench.json",
  ];
  for (const f of need) ensure(existsSync(resolve(args.src, f)), `${f} missing — run the workbench builders first (see docs/hgab-data.md)`);
  mkdirSync(args.out, { recursive: true });
  const commit = execFileSync("git", ["-C", args.src, "rev-parse", "HEAD"], { encoding: "utf8" }).trim();
  const builtAt = new Date().toISOString();
  log(`import:hgab  src=${args.src} @ ${commit.slice(0, 12)}  out=${args.out}  datasets=${args.datasets.join(",")}${args.pdf ? "" : "  --no-pdf"}\n`);

  const main = readJson<{ workspaces: MainWorkspace[]; input_provenance: Record<string, { path: string; sha256: string }> }>(resolve(args.src, "analysis/data/main_overview_2027.json"));
  const ws = (k: DatasetKey) => {
    const w = main.workspaces.find((x) => x.key === k);
    ensure(w, `main_overview has no ${k} workspace`);
    return w;
  };

  const results: Partial<Record<DatasetKey, { meta: HgabDatasetMeta; summary: DatasetSummary; rows: OutRow[]; docPages: Record<string, number[]> }>> = {};
  const fmrWb = readJson<AnnexWorkbench>(resolve(args.src, "other-analysis/data/fmr_workbench.json"));
  for (const key of args.datasets) {
    log(`building ${key}`);
    if (key === "dpwh") results.dpwh = buildDpwh(args.src, ws("dpwh"));
    if (key === "fmr") results.fmr = buildAnnex("fmr", fmrWb, DOC.nepFmr, ws("fmr"));
    if (key === "hfep") results.hfep = buildHfep(readJson<HfepWorkbench>(resolve(args.src, "other-analysis/data/hfep_workbench.json")), ws("hfep"));
    if (key === "nia") results.nia = buildAnnex("nia", readJson<AnnexWorkbench>(resolve(args.src, "analysis-nia/data/nia_workbench.json")), DOC.nepNia, ws("nia"));
    const r = results[key]!;
    const b = r.meta.bridge;
    log(`  rows ${r.rows.length.toLocaleString()} · NEP ${peso(r.meta.totals.nep_php)} · House ${peso(r.meta.totals.hgab3_php)} · bridge net ${peso(b.net_php)} (house_only ${b.house_only.rows}, nep_only ${b.nep_only.rows}, unchanged ${b.unchanged.rows}, +${b.increased.rows}, −${b.decreased.rows}, scope ${b.scope_review.rows})`);
  }

  const used: Record<string, number[]> = {};
  for (const r of Object.values(results)) for (const [k, pages] of Object.entries(r.docPages)) used[k] = [...(used[k] ?? []), ...pages];
  const documents = buildDocuments(args.src, used);

  log("\nreconciliation against our FY2027 NEP tree");
  const reconciliation = reconcile(args.nep, args.src, results);
  const tally = { exact: 0, explained: 0, mismatch: 0, info: 0 };
  for (const r of reconciliation) tally[r.status]++;
  for (const r of reconciliation.filter((x) => x.status === "mismatch")) log(`  ✗ ${r.dataset} ${r.check}: ours ${peso(r.ours_php)} theirs ${peso(r.theirs_php)} — ${r.note}`);
  log(`  ${tally.exact} exact · ${tally.explained} explained · ${tally.info} info · ${tally.mismatch} mismatch`);

  log("\nwriting");
  const datasetsOut: Record<string, unknown> = {};
  for (const key of args.datasets) {
    const r = results[key]!;
    const dir = resolve(args.out, key);
    mkdirSync(dir, { recursive: true });
    writeFileSync(resolve(dir, "summary.json"), `${JSON.stringify(r.summary)}\n`);
    const pq = await writeParquet(r.rows, dir);
    datasetsOut[key] = { totals: r.meta.totals, counts: r.meta.counts, printed: r.meta.printed, comparison_rows: r.rows.length, parquet: { rows: pq.rows, bytes: pq.bytes }, bridge_asserted_against: "analysis/data/main_overview_2027.json" };
    log(`  ${key}/summary.json · ${key}/projects.parquet (${pq.rows.toLocaleString()} rows, ${(pq.bytes / 1e6).toFixed(1)} MB)`);
  }

  const overview = {
    fiscal_year: FISCAL_YEAR, built_at: builtAt, source_repo: SOURCE_REPO, source_commit: commit,
    datasets: args.datasets.map((k) => results[k]!.meta), documents, reconciliation,
  };
  writeFileSync(resolve(args.out, "overview.json"), `${JSON.stringify(overview)}\n`);
  log("  overview.json");

  const pdfs: Array<Record<string, unknown>> = [];
  if (args.pdf) mkdirSync(resolve(args.out, "pdf"), { recursive: true });
  for (const d of documents) {
    const dest = resolve(args.out, "pdf", `${d.key}.pdf`);
    let copied = false;
    if (args.pdf) {
      if (!existsSync(dest) || statSync(dest).size !== d.bytes || sha256(dest) !== d.sha256) { copyFileSync(resolve(args.src, DOC_SOURCES[d.key]), dest); copied = true; }
    }
    pdfs.push({ key: d.key, source_path: DOC_SOURCES[d.key], sha256: d.sha256, bytes: d.bytes, copied, present: existsSync(dest) });
  }
  if (args.pdf) log(`  pdf/ (${pdfs.filter((p) => p.copied).length} copied, ${pdfs.length} total)`);

  const inputs: Record<string, { sha256: string; bytes: number }> = {};
  for (const f of [
    ...need, "analysis/data/house_reading_changes_2027.json", "analysis/data/source_comparison_2027.json", "analysis/data/stage_trace_2027.json",
    "analysis/data/nep_2027_source_projects.json", "analysis/data/nep_2027_tree.json", "analysis/data/road_group_candidates_2027.json", "analysis/data/chainage_units_2027.json",
  ]) {
    const p = resolve(args.src, f);
    if (existsSync(p)) inputs[f] = { sha256: sha256(p), bytes: statSync(p).size };
  }
  const ours: Record<string, { sha256: string; bytes: number }> = {};
  for (const f of ["18/summary.json", "18/fpaps.json", "05/fpaps.json", "13/expenses.json", "35/fpaps.json"]) {
    const p = resolve(args.nep, f);
    if (existsSync(p)) ours[f] = { sha256: sha256(p), bytes: statSync(p).size };
  }
  const fmrShim = typeof fmrWb.build_note === "string";
  const builders = [
    { step: "npm ci --prefix analysis/web", status: "ok" },
    { step: "node analysis/web/buildComparisonData.mjs", status: existsSync(resolve(args.src, "analysis/data/comparison_projects_2027.json")) ? "ok" : "missing", outputs: ["analysis/data/comparison_overview_2027.json", "analysis/data/comparison_projects_2027.json"] },
    { step: "python3 other-analysis/build_fmr_final_dataset.py", status: existsSync(resolve(args.src, "other-analysis/data/hgab_fmr_final_dataset.json")) ? "ok" : "failed", note: "Needs the philippines-psgc-shapefiles content inside the dpwh_coor2psgc_geomapping submodule and geo libraries (shapely/pyshp); neither is available on the build host. Only the PSGC enrichment depends on it." },
    { step: "python3 other-analysis/build_fmr_workbench.py", status: fmrShim ? "shim" : "ok", note: fmrShim ? fmrWb.build_note : undefined, outputs: ["other-analysis/data/fmr_workbench.json"] },
    { step: "python3 other-analysis/build_hfep_workbench.py", status: "ok", outputs: ["other-analysis/data/hfep_workbench.json"] },
    { step: "python3 analysis-nia/build_nia_workbench.py", status: "ok", outputs: ["analysis-nia/data/nia_workbench.json"] },
    { step: "node analysis/web/buildMainOverview.mjs", status: "ok", outputs: ["analysis/data/main_overview_2027.json"] },
  ];
  const manifest = {
    fiscal_year: FISCAL_YEAR, built_at: builtAt, source_repo: SOURCE_REPO, source_commit: commit, source_checkout: args.src,
    datasets_built: args.datasets, builders, inputs, main_overview_input_provenance: main.input_provenance, our_nep_tree: { path: args.nep, files: ours },
    datasets: datasetsOut, documents: pdfs, pdfs_copied: args.pdf,
    reconciliation: { ...tally, rows: reconciliation.length },
    layout: ["manifest.json", "overview.json", "<dataset>/summary.json", "<dataset>/projects.parquet", "pdf/<doc_key>.pdf"],
    columns: PROJECT_COLUMNS, column_types: COLUMN_TYPES,
  };
  writeFileSync(resolve(args.out, "manifest.json"), `${JSON.stringify(manifest, null, 2)}\n`);
  log("  manifest.json");
  if (tally.mismatch) log(`\n${tally.mismatch} reconciliation mismatch(es) — the verifier will fail.`);
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});
